# concepts:
# unique color identification, object detection, transformation

# description:
# Identify all connected components (objects) in the grid. Select the object whose color is unique and not shared
# by any other object. This unique-colored object becomes the guide object, and its color is changed to red in the output grid.

def main(input_grid):
    # Detect all objects in the grid
    objects = find_connected_components(input_grid, connectivity=4, monochromatic=True)

    # Dictionary to count the occurrence of each color
    color_count = {}

    # Count how many objects share each color
    for obj in objects:
        color = None
        for x, y in np.argwhere(obj != Color.BLACK):
            color = obj[x, y]
            break  # All pixels in the object have the same color, so we break after finding the first one
        if color:
            if color in color_count:
                color_count[color] += 1
            else:
                color_count[color] = 1

    # Find the unique color
    unique_color = None
    for color, count in color_count.items():
        if count == 1:
            unique_color = color
            break

    # Find and highlight the unique-colored object
    output_grid = input_grid.copy()
    for obj in objects:
        if unique_color is not None:
            x, y, _, _ = bounding_box(obj, background=Color.BLACK)
            if obj[x, y] == unique_color:
                obj[obj != Color.BLACK] = Color.RED
        blit_object(output_grid, obj, background=Color.BLACK)

    return output_grid

