    # Create random objects with random colors
    color_palette = list(Color.NOT_BLACK)
    np.random.shuffle(color_palette)

    num_objects = np.random.randint(3, 6)
    for _ in range(num_objects):
        obj_color = np.random.choice(color_palette)
        obj = random_sprite(np.random.randint(2, 4), np.random.randint(2, 4), color_palette=[obj_color])
        try:
            x, y = random_free_location_for_sprite(grid, obj, padding=1, background=Color.BLACK)
            blit_sprite(grid, obj, x, y)
        except ValueError:
            continue  # If we can't place the object, skip it

    # Ensure there is at least one unique-colored object
    objects = find_connected_components(grid, connectivity=4, monochromatic=True)
    color_count = {}
    for obj in objects:
        color = None
        for x, y in np.argwhere(obj != Color.BLACK):
            color = obj[x, y]
            break
        if color:
            if color in color_count:
                color_count[color] += 1
            else:
                color_count[color] = 1

    # If no unique color exists, regenerate input
    if not any(count == 1 for count in color_count.values()):
        return generate_input()

    return grid

from common import *

import numpy as np
from typing import *

# concepts:
# unique_color_object, connected components

# description:
# The input consists of a grid with various colored objects. Each object is a connected component, and each is monochromatic.
# The task is to identify the object whose color is unique (not shared by any other object in the grid).
# In the output, this unique-colored object should be highlighted by changing its color to a bright color (e.g., yellow).

def main(input_grid):
    # Extract all objects, assuming they are monochromatic and connected by 8-way connectivity
    objects = find_connected_components(input_grid, background=Color.BLACK, connectivity=8, monochromatic=True)

    # Count occurrences of each color across all objects
    color_count = {}
    for obj in objects:
        obj_color = obj[obj != Color.BLACK][0]
        if obj_color in color_count:
            color_count[obj_color] += 1
        else:
            color_count[obj_color] = 1

    # Identify the unique-colored object
    unique_color = None
    for color, count in color_count.items():
        if count == 1:
            unique_color = color
            break

    # Create the output grid
    output_grid = input_grid.copy()

    # Highlight the unique-colored object by changing its color to yellow
    if unique_color is not None:
        for obj in objects:
            if np.any(obj == unique_color):
                obj[obj != Color.BLACK] = Color.YELLOW
                blit_object(output_grid, obj)

    return output_grid


def generate_input():
    # Define the grid size
    n, m = np.random.randint(5, 10), np.random.randint(5, 10)
    grid = np.full((n, m), Color.BLACK)

    # Generate random objects with random colors
    num_objects = np.random.randint(3, 6)
    color_palette = list(Color.NOT_BLACK)
    np.random.shuffle(color_palette)

    for _ in range(num_objects):
        obj_color = color_palette.pop()
        obj = random_sprite(n=list(range(1, 4)), m=list(range(1, 4)), color_palette=[obj_color], connectivity=8)
        try:
            x, y = random_free_location_for_sprite(grid, obj, padding=1)
            blit_sprite(grid, obj, x, y)
        except ValueError:
            continue

    # Ensure there's at least one unique-colored object
    objects = find_connected_components(grid, background=Color.BLACK, connectivity=8, monochromatic=True)
    color_count = {}
    for obj in objects:
        obj_color = obj[obj != Color.BLACK][0]
        if obj_color in color_count:
            color_count[obj_color] += 1
        else:
            color_count[obj_color] = 1

    if not any(count == 1 for count in color_count.values()):
        return generate_input()

    return grid
